solution.Solution.cs:
public static class Shell
{
    public static string Run(string line) => line.Split(' ', StringSplitOptions.RemoveEmptyEntries) switch
    {
        [] => "",
        ["help"] => "commands: add, remove, list",
        ["add", var item] => $"added {item}",
        ["add", var item, var qty] when int.TryParse(qty, out int n) && n > 0 => $"added {n} x {item}",
        ["add", ..] => "usage: add <item> [qty]",
        ["remove", var item] => $"removed {item}",
        ["list"] => "nothing yet",
        [var first, ..] => $"unknown command: {first}",
    };
}

unitTests:
Test("simple commands", () =>
{
    CheckEq(Shell.Run(""), "");
    CheckEq(Shell.Run("help"), "commands: add, remove, list");
    CheckEq(Shell.Run("list"), "nothing yet");
    CheckEq(Shell.Run("remove tea"), "removed tea");
});

Test("add with and without a quantity", () =>
{
    CheckEq(Shell.Run("add tea"), "added tea");
    CheckEq(Shell.Run("add  tea   3"), "added 3 x tea");
    CheckEq(Shell.Run("add tea 0"), "usage: add <item> [qty]");
    CheckEq(Shell.Run("add tea lots"), "usage: add <item> [qty]");
    CheckEq(Shell.Run("add"), "usage: add <item> [qty]");
});

Test("unknown", () =>
{
    CheckEq(Shell.Run("fly to the moon"), "unknown command: fly");
    CheckEq(Shell.Run("remove"), "unknown command: remove");
});

